param([string]$Root=(Join-Path $PSScriptRoot '최종 수정 파일'))
$ErrorActionPreference='Stop'
$manifest=Get-Content -LiteralPath (Join-Path $Root 'client-manifest.json') -Raw -Encoding UTF8|ConvertFrom-Json
function Save([string]$p,[string[]]$lines){[IO.File]::WriteAllText($p,($lines -join "`n"),[Text.UTF8Encoding]::new($false))}
$modules=@('Portal Hero','Client Vision','Mood Intake','Signature Experience','Mixology Canvas','Product Constellation','Ritual Player','Bundle Atelier','Subscription Rhythm','Community Loop','Evidence Drawer','Saved Ritual CTA')
$products=@('Aurora Cold Brew','Midnight GABA','Zero Sugar Earl Grey','Botanical Sparkling','Calm Blue Chamomile','Focus Citrus Mate','Sleep Lavender Rooibos','Vegan Berry Tonic','Three-Minute Office Stick','Mood Dial Sampler','Glass Ritual Kit','Mixology Shaker Set','Initial Tin Gift','Family Zero-Caffeine Pack','Senior Easy-Brew Pack','Thirty-Day Rhythm Box','Hydration Beauty Blend','Upcycle Refill Pouch','Hotel Welcome Pairing','Architect Table Set')
foreach($c in $manifest.clients){
 $id=[string]$c.id;$name=[string]$c.name;$key="${id}_${name}";$homeId="W$id-HOME";$diag="W$id-DIAG";$mix="W$id-MIX";$rit="W$id-RITUAL";$build="W$id-BUILD";$comm="W$id-COMM";$done="W$id-DONE"
 $flowDir=Join-Path $Root "서비스 흐름도\$key";$screenDir=Join-Path $Root "화면 설계서\$key"
 $mermaid=@("flowchart LR","  A[$homeId 몰입 진입] --> B[$diag 상태 입력]","  B --> C{추천 가능?}","  C -->|예| D[$mix 레시피 3안 비교]","  C -->|아니오| E[조건 완화·전체 탐색]","  E --> D","  D --> F[$rit 180초 체험]","  F --> G[$build 번들 설계]","  G --> H{저장 성공?}","  H -->|예| I[$comm 기록·공유]","  H -->|아니오| J[입력 유지·재시도]","  J --> G","  I --> K[$done 완료]")
 Save (Join-Path $flowDir '서비스_흐름도.mmd') $mermaid
 $flow=@('# WICKETA '+$name+' 서비스 흐름도','','## 고유 여정','','- 클라이언트: '+$id+' · '+$name,'- 콘셉트: '+$c.concept,'- 레이아웃: '+$c.layout,'- 핵심 인터랙션: '+$c.killerFeature,'- 상위 문서: [사이트맵](../../사이트맵/'+$key+'/사이트맵.md)','','## 정상 흐름','','1. `'+$homeId+'`에서 세계관 진입','2. `'+$diag+'`에서 감정·가용 시간·민감도 선택','3. `'+$mix+'`에서 믹솔로지 레시피 3안 비교','4. `'+$rit+'`에서 수색 변화와 180초 타이머 체험','5. `'+$build+'`에서 제품·구독·패키지 조합','6. `'+$comm+'`에서 리추얼 저장 또는 공유','7. `'+$done+'`에서 레시피 ID 확인','','## 오류와 대안','','- 진단 결과 없음: 조건 완화와 전체 탐색 제공','- 재고 없음: 동일 감정 목표의 대체 베이스 티 제안','- 타이머 중단: 남은 시간과 레시피를 보존','- 저장 실패: 조합값 유지 후 재시도·복사 제공','- 접근성 모드: 사운드 없이 텍스트 진행 상태 제공','','```mermaid')+$mermaid+@('```')
 Save (Join-Path $flowDir '서비스_흐름도.md') $flow
 $flowSvg="<svg xmlns='http://www.w3.org/2000/svg' width='1440' height='900' role='img' aria-labelledby='t d'><title id='t'>WICKETA $name 서비스 흐름도</title><desc id='d'>$($c.concept) 진단·믹솔로지·리추얼·저장 흐름</desc><rect width='1440' height='900' fill='#f4f0e8'/><style>.n{fill:#fff;stroke:#171824;stroke-width:2}.e{fill:#f9dfe9;stroke:#a43b66;stroke-width:2}.h{font:700 28px Arial;fill:#171824}.s{font:18px Arial;fill:#171824}.l{stroke:#6757d9;stroke-width:3}</style><text x='70' y='65' class='h'>WICKETA $id · $($c.concept)</text><rect class='n' x='70' y='140' width='240' height='110' rx='24'/><text class='s' x='95' y='205'>감정·상황 진단</text><line class='l' x1='310' y1='195' x2='390' y2='195'/><rect class='n' x='400' y='140' width='240' height='110' rx='24'/><text class='s' x='425' y='205'>믹솔로지 3안</text><line class='l' x1='640' y1='195' x2='720' y2='195'/><rect class='n' x='730' y='140' width='240' height='110' rx='24'/><text class='s' x='755' y='205'>180초 리추얼</text><line class='l' x1='970' y1='195' x2='1050' y2='195'/><rect class='n' x='1060' y='140' width='240' height='110' rx='24'/><text class='s' x='1085' y='205'>번들·구독 저장</text><line class='l' x1='1180' y1='250' x2='1180' y2='370'/><rect class='n' x='1060' y='380' width='240' height='110' rx='24'/><text class='s' x='1085' y='445'>기록·커뮤니티</text><line class='l' x1='1060' y1='435' x2='980' y2='435'/><rect class='n' x='730' y='380' width='240' height='110' rx='24'/><text class='s' x='755' y='445'>Saved Ritual</text><line class='l' x1='850' y1='490' x2='850' y2='610'/><rect class='e' x='730' y='620' width='240' height='110' rx='24'/><text class='s' x='755' y='675'>오류·대체 제안</text><text class='s' x='755' y='705'>입력과 조합 유지</text></svg>"
 [IO.File]::WriteAllText((Join-Path $flowDir '서비스_흐름도.svg'),$flowSvg,[Text.UTF8Encoding]::new($false))
 $screen=@('# WICKETA '+$name+' 인터랙션 설계서','','## 개인화 설계','','- 클라이언트: '+$id+' · '+$name,'- 콘셉트: '+$c.concept,'- 레이아웃: '+$c.layout,'- 킬러 기능: '+$c.killerFeature,'- 사이트맵: [열기](../../사이트맵/'+$key+'/사이트맵.md)','- 서비스 흐름도: [열기](../../서비스%20흐름도/'+$key+'/서비스_흐름도.md)','','## WICKETA 전용 12개 모듈','','| 모듈 ID | 이름 | 역할 |','|---|---|---|')
 for($i=0;$i -lt 12;$i++){$screen += ('| WK-SEC-{0:D2} | {1} | {2} |' -f ($i+1),$modules[$i],@('몰입형 세계관 진입','클라이언트 관점','감정·시간 진단','고유 킬러 기능','향·맛 조합','비선형 상품 탐색','180초 체험','번들 설계','구독 주기','저장·공유','근거·정책','리추얼 저장')[$i])}
 $screen += @('','## 상품 20개 경험별 분산','','| 상품 ID | 상품 | 노출 맥락 |','|---|---|---|')
 for($i=0;$i -lt 20;$i++){$screen += ('| WK-P{0:D2} | {1} | {2} |' -f ($i+1),$products[$i],@('Hero 오브젝트','믹솔로지 비교','리추얼 추천','번들 빌더','구독·커뮤니티')[$i%5])}
 $screen += @('','## 상태와 접근성','','- 진단·믹솔로지·타이머·번들·커뮤니티별 기본·로딩·빈 결과·오류·완료 상태','- `h1` 1개와 12개 `section` 랜드마크','- 입력 레이블, `aria-live`, 대화상자 포커스 이동·복귀','- 사운드 자동재생 금지와 텍스트 대체','- 고대비·모션 축소·키보드 전용 이용 지원')
 Save (Join-Path $screenDir '화면_설계서.md') $screen
}
Write-Output 'Repaired WICKETA service-flow and screen-spec documents.'

